public String getLink(String linkId, String fallbackUrl) {
    return this.links.getOrDefault(linkId, fallbackUrl);
}

private void initialize() {
    this.httpClient = HttpClient.newHttpClient();
    Path configDir = Platform.getConfigFolder().resolve("adorablehamsterpets");
    this.cacheFilePath = configDir.resolve("links.cache.json");
    try {
        Files.createDirectories(configDir, new FileAttribute[0]);
    }
    catch (IOException e) {
        AdorableHamsterPets.LOGGER.error("[RemoteLinks] Failed to create config directory.", (Throwable)e);
