public class ModSpawnPlacementsImpl {
    private static final List<SpawnPlacementData<?>> PENDING_PLACEMENTS = new ArrayList();

    public static <T extends Mob> void register(Supplier<? extends EntityType<T>> entityTypeSupplier, SpawnPlacements.Type location, Heightmap.Types heightmapType, SpawnPlacements.SpawnPredicate<T> predicate) {
        PENDING_PLACEMENTS.add(new SpawnPlacementData<T>(entityTypeSupplier, location, heightmapType, predicate));
    }

    @SubscribeEvent
    public static void onRegisterSpawnPlacements(SpawnPlacementRegisterEvent event) {
        for (SpawnPlacementData<?> data : PENDING_PLACEMENTS) {
            data.register(event);
        }
        PENDING_PLACEMENTS.clear();
    }

    private record SpawnPlacementData<T extends Mob>(Supplier<? extends EntityType<T>> entityTypeSupplier, SpawnPlacements.Type location, Heightmap.Types heightmapType, SpawnPlacements.SpawnPredicate<T> predicate) {
        void register(SpawnPlacementRegisterEvent event) {
            event.register(this.entityTypeSupplier.get(), this.location, this.heightmapType, this.predicate, SpawnPlacementRegisterEvent.Operation.REPLACE);
        }
    }
}

